// runner/render/render-snippet-fill.ts
// Phase 75 Plan 05 (DEDUP-01) — shared awaiting-snippet-fill renderer helpers.
import { CSS_CLASS } from '../../constants/css-classes';
//
// Owns:
//   - "Loading snippet..." placeholder paragraph rendered while host loads the
//     snippet asynchronously.
//   - "Snippet '{id}' not found" copy emitted when the host's load returns null.
//   - Phase 51 D-14 path-shape detection — distinguishes legacy id-string callers
//     (Phase 32/35) from full-vault-path callers (Phase 51 auto-insert).
//
// Hosts retain:
//   - Snippet path resolution (InlineRunnerModal WR-03 + basename fallback scan).
//   - SnippetFillInModal lifecycle (`fillModal`/`isFillModalOpen` gate is host-owned).
//   - Validation-error chrome (Notice copy + stepBack/render policy is host-owned).
//   - completeSnippet dispatch + autosave / accumulator-delta append + re-render.

/** Phase 51 D-14 path-shape detection shared with InlineRunnerModal handleSnippetFill. */
export function isFullSnippetPath(snippetId: string): boolean {
  return snippetId.includes('/') ||
    snippetId.endsWith('.md') ||
    snippetId.endsWith('.json');
}

/** Render the "Loading snippet..." placeholder. Host calls this synchronously
 *  before kicking off the async snippet load. */
export function renderSnippetFillLoading(zone: HTMLElement): void {
  zone.createEl('p', {
    text: 'Loading snippet...',
    cls: CSS_CLASS.EMPTY_STATE_BODY,
  });
}

export interface SnippetFillNotFoundOptions {
  /** Optional trailing copy appended to the base "Snippet '{id}' not found." line.
   *  Legacy hosts may pass the " The snippet may have been deleted. Use
   *  step-back to continue." trailer; inline modal omits it. */
  trailer?: string;
}

/** Replace the zone with a localised not-found message. */
export function renderSnippetFillNotFound(
  zone: HTMLElement,
  snippetId: string,
  options: SnippetFillNotFoundOptions = {},
): void {
  zone.empty();
  const trailer = options.trailer ?? '';
  zone.createEl('p', {
    text: `Snippet '${snippetId}' not found.${trailer}`,
    cls: CSS_CLASS.EMPTY_STATE_BODY,
  });
}

// runner/render/render-snippet-picker.ts
// Phase 75 Plan 04 (DEDUP-01) — shared awaiting-snippet-pick renderer.
//
// Owns:
//   - host-class wrapper div + SnippetTreePicker construction (file-only mode)
//   - stale-result guard (state status + nodeId)
//   - optional DOM-attached guard (inline modal)
//   - localised not-found / validation-error dispatch via host copy
//   - shared Back footer
//
// Hosts retain:
//   - SnippetTreePicker instance lifetime (returned from this function so the
//     host can call unmount() on state-change / step-back)
//   - autosave / accumulator-delta side effects
//   - snippet placeholder modal flow (handleSnippetPickerSelection)
//   - re-render entry point
//
// Historical Phase 75 shared picker extraction plan.
import type { App } from 'obsidian';
import type { Snippet } from '../../snippets/snippet-model';
import type { SnippetService } from '../../snippets/snippet-service';
import type { RunnerState } from '../runner-state';
import type { Translator } from '../../i18n';
import { CSS_CLASS } from '../../constants/css-classes';
import { SnippetTreePicker } from '../../views/snippet-tree-picker';
import { renderRunnerFooter, type RunnerFooterHost } from './render-footer';

type AwaitingSnippetPickState = Extract<RunnerState, { status: 'awaiting-snippet-pick' }>;

type SnippetPickerHostClass = typeof CSS_CLASS.STP_INLINE_HOST;

/** Host-supplied copy for async errors surfaced by the picker. */
export interface SnippetPickerCopy {
  /** Snippet at the picked path could not be loaded. */
  notFound(relativePath: string): string;
  /** JSON snippet loaded but carries a non-null validationError. */
  validationError(snippetPath: string, validationMessage: string): string;
}

export interface SnippetPickerRenderOptions extends RunnerFooterHost {
  app: App;
  snippetService: SnippetService;
  /** Optional translator for footer aria-labels. */
  t?: Translator;
  /** Vault-relative root path (plugin.settings.snippetFolderPath). */
  rootPath: string;
  /** Host wrapper CSS hook. Inline modal: rp-stp-inline-host. */
  hostClass: SnippetPickerHostClass;
  /** Copy locale (EN divergence preserved unless explicitly merged). */
  copy: SnippetPickerCopy;
  /** Returns the runner's current awaiting-snippet-pick nodeId, or null if the
   *  state has changed (advanced/stepped-back/error/etc). T-30-04 stale-result guard. */
  getCurrentNodeId(): string | null;
  /** Optional DOM-attached guard. Inline modal returns
   *  `document.body.contains(this.containerEl)`. */
  isStillMounted?(): boolean;
  /** Host-controlled async error presentation. Default: empty `questionZone`
   *  and append a `.rp-empty-state-body` paragraph in place. Inline modal
   *  overrides to call its own `render()` first and write to the fresh zone. */
  presentAsyncError?(message: string): void;
  /** Called when a usable snippet is loaded. Host advances runner / autosaves /
   *  appends accumulator delta / re-renders. */
  onSnippetReady(snippet: Snippet): void | Promise<void>;
  /** Footer back-button handler. Host owns picker.unmount + runner.stepBack +
   *  any host-specific autosave + re-render. */
  onBack(): void;
  /** Footer redo-button handler. Host calls runner.redo + re-render. */
  onRedo?(): void;
}

export function renderSnippetPicker(
  questionZone: HTMLElement,
  state: AwaitingSnippetPickState,
  options: SnippetPickerRenderOptions,
): SnippetTreePicker {
  const { app, snippetService, rootPath, hostClass, copy } = options;
  const nodeRootRel = state.subfolderPath ?? '';
  const nodeRootAbs = nodeRootRel === '' ? rootPath : `${rootPath}/${nodeRootRel}`;

  questionZone.empty();
  const pickerHost = questionZone.createDiv({ cls: hostClass });

  const capturedNodeId = state.nodeId;

  const presentAsyncError = options.presentAsyncError ?? ((message: string) => {
    questionZone.empty();
    questionZone.createEl('p', { cls: CSS_CLASS.EMPTY_STATE_BODY, text: message });
  });

  const picker = new SnippetTreePicker({
    app,
    snippetService,
    container: pickerHost as unknown as HTMLElement,
    mode: 'file-only',
    rootPath: nodeRootAbs,
    onSelect: (result) => {
      void (async () => {
        const absPath = result.relativePath === ''
          ? nodeRootAbs
          : `${nodeRootAbs}/${result.relativePath}`;
        const snippet = await snippetService.load(absPath);

        // T-30-04 stale-result guard: bail if runner advanced / stepped-back
        // during the await.
        if (options.getCurrentNodeId() !== capturedNodeId) return;
        // CR-01 (inline-only): bail if the host DOM was detached.
        if (options.isStillMounted !== undefined && !options.isStillMounted()) return;

        if (snippet === null) {
          presentAsyncError(copy.notFound(result.relativePath));
          return;
        }
        if (snippet.kind === 'json' && snippet.validationError !== null) {
          presentAsyncError(copy.validationError(snippet.path, snippet.validationError));
          return;
        }
        await options.onSnippetReady(snippet);
      })();
    },
  });
  void picker.mount();

  renderRunnerFooter(questionZone, options, {
    showBack: state.canStepBack,
    onBack: options.onBack,
    showRedo: state.canRedo,
    onRedo: options.onRedo,
    t: options.t,
  });

  return picker;
}

// snippets/protocol-ref-sync.ts
// Vault-wide utility: rewrite snippetPath / subfolderPath references in every
// .rp.json protocol file when a snippet file or folder is moved.

import type { App, TFile } from 'obsidian';
import { isProtocolDocumentV1, type ProtocolDocumentV1 } from '../protocol/protocol-document';
import { WriteMutex } from '../utils/write-mutex';

interface ProtocolSyncResult {
  updated: string[];
  skipped: Array<{ path: string; reason: string }>;
}

// Module-level mutex for protocol writes. Key = protocol file path.
const protocolMutex = new WriteMutex();

/**
 * Rewrite fields.snippetPath and fields.subfolderPath on snippet nodes across
 * every .rp.json file in the vault, given an old→new path mapping.
 *
 * Matching rules (same as canvas-ref-sync):
 *   - Exact match: path === oldKey → replace with newValue.
 *   - Prefix match with `/` boundary: path.startsWith(oldKey + '/')
 *     → replace prefix, keeping the trailing segment(s).
 *
 * Semantics:
 *   - Only nodes with kind === 'snippet' are considered.
 *   - Empty-string / null / missing snippetPath or subfolderPath → skipped.
 *   - Best-effort: a read/parse/write failure on one file is recorded in `skipped`
 *     and does not abort the loop. Never throws.
 *   - No-op early return: a file whose parsed JSON contains no matching snippet
 *     nodes is not written (avoids churn and mtime bumps).
 *
 * @param app Obsidian App
 * @param mapping old path → new path (paths are relative to settings.snippetFolderPath)
 */
export async function rewriteProtocolSnippetRefs(
  app: App,
  mapping: Map<string, string>,
): Promise<ProtocolSyncResult> {
  const updated: string[] = [];
  const skipped: Array<{ path: string; reason: string }> = [];

  if (mapping.size === 0) return { updated, skipped };

  const protocolFiles: TFile[] = app.vault
    .getFiles()
    .filter((f) => f.path.endsWith('.rp.json'));

  for (const file of protocolFiles) {
    await protocolMutex.runExclusive(file.path, async () => {
      try {
        const raw = await app.vault.read(file);
        let parsed: ProtocolDocumentV1;
        try {
          parsed = JSON.parse(raw) as ProtocolDocumentV1;
        } catch (e) {
          const reason = `invalid JSON: ${(e as Error).message}`;
          console.error('[RadiProtocol] protocol-ref-sync:', file.path, reason);
          skipped.push({ path: file.path, reason });
          return;
        }

        if (!isProtocolDocumentV1(parsed)) {
          skipped.push({ path: file.path, reason: 'invalid protocol document schema' });
          return;
        }

        let mutated = false;
        for (const node of parsed.nodes) {
          if (node.kind !== 'snippet') continue;

          const snippetPath = node.fields?.snippetPath;
          if (typeof snippetPath === 'string' && snippetPath !== '') {
            const rewritten = applyMapping(snippetPath, mapping);
            if (rewritten !== null && rewritten !== snippetPath) {
              node.fields.snippetPath = rewritten;
              mutated = true;
            }
          }

          const subfolderPath = node.fields?.subfolderPath;
          if (typeof subfolderPath === 'string' && subfolderPath !== '') {
            const rewritten = applyMapping(subfolderPath, mapping);
            if (rewritten !== null && rewritten !== subfolderPath) {
              node.fields.subfolderPath = rewritten;
              mutated = true;
            }
          }
        }

        if (!mutated) return;

        try {
          const next = JSON.stringify(parsed, null, 2) + '\n';
          await app.vault.modify(file, next);
          updated.push(file.path);
        } catch (e) {
          const reason = `write failed: ${(e as Error).message}`;
          console.error('[RadiProtocol] protocol-ref-sync:', file.path, reason);
          skipped.push({ path: file.path, reason });
        }
      } catch (e) {
        const reason = `read failed: ${(e as Error).message}`;
        console.error('[RadiProtocol] protocol-ref-sync:', file.path, reason);
        skipped.push({ path: file.path, reason });
      }
    });
  }

  return { updated, skipped };
}

/**
 * Apply old→new mapping to a single path.
 * Returns the rewritten path, or null if no mapping key matched.
 * Exact match wins over prefix match. Longest prefix wins on ties.
 */
function applyMapping(
  current: string,
  mapping: Map<string, string>,
): string | null {
  // Exact match
  const exact = mapping.get(current);
  if (exact !== undefined) return exact;

  // Prefix match with `/` boundary — pick the longest matching key
  let bestKey: string | null = null;
  for (const key of mapping.keys()) {
    if (current.startsWith(key + '/')) {
      if (bestKey === null || key.length > bestKey.length) bestKey = key;
    }
  }
  if (bestKey === null) return null;
  const newPrefix = mapping.get(bestKey)!;
  return newPrefix + current.slice(bestKey.length);
}

